<span data-state="{{ $state }}" style="display:inline-block; min-width:{{ $sz }}px; height:{{ $sz }}px; line-height:{{ $sz }}px; padding:0 {{ ($label ?? false) ? 8 : 0 }}px; border-radius:{{ (int) ($sz / 3.2) }}px; text-align:center; font-size:{{ (int) ($sz * 0.62) }}px; font-weight:800; background-color:{{ \App\Domains\Notifications\Support\DigestStatus::CELL[$state] }}; color:{{ \App\Domains\Notifications\Support\DigestStatus::INK[$state] }};">{{ \App\Domains\Notifications\Support\DigestStatus::GLYPH[$state] }}@if ($label ?? false) <span style="font-size:{{ (int) ($sz * 0.55) }}px;">{{ \App\Domains\Notifications\Support\DigestStatus::label($state, $dir === 'rtl') }}</span>@endif</span>
